function CountInRange(arr: array<int>, low: int, high: int): int
    requires arr != null
    requires low <= high
    ensures 0 <= CountInRange(arr, low, high) <= |arr|
{
    var count := 0;
    var i := 0;
    while i < |arr|
        invariant 0 <= count <= i
    {
        if arr[i] >= low && arr[i] <= high {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function Reverse(arr: array<string>): array<string>
    requires arr != null
    ensures |Reverse(arr)| == |arr|
{
    var result := new string[|arr|];
    var i := 0;
    while i < |arr|
        invariant 0 <= i <= |arr|
    {
        result[i] := arr[|arr| - 1 - i];
        i := i + 1;
    }
    return result;
}

